    dist[start] = 0
    q = []  # 各要素は，(startからある頂点vまでの仮の距離, 頂点vのID)からなるタプル
    heapq.heappush(q, (0, start))  # 始点をpush
    while len(q) != 0:
        prov_cost, v_m = heapq.heappop(q)  # pop  # 一度取り出された時点でコストは確定
        v, m_v = v_m

        # プライオリティキューに格納されている最短距離が
        # 現在計算できている最短距離より大きければ，distの更新をする必要はない
        if dist[v] < prov_cost:
            continue

        if v==N:
