def dijkstra(s):
    dist = [INF]*n
    dist[s] = 0
    que = [(0, s)]
    while que:
        cost, s = heappop(que)
        if dist[s] < cost:
            continue
        for t, d in G[s]:
            if cost + d < dist[t]:
                dist[t] = cost + d
                heappush(que, (cost + d, t))
    ma = max(dist)
    assert ma != INF
    goal = [i for i in range(n) if dist[i] == ma]
    used = set(goal)
    deq = deque(goal)
    while deq:
        s = deq.popleft()
        for t, d in G[s]:
            if dist[t] + d == dist[s] and t not in used:
                used.add(t)
                deq.append(t)
    return ma, used

